_file_map = {

    "diagnostic.baml": "// BAML Schema for RAG Failure Diagnostics\n\nenum FailureCategory {\n    ManifestBlock        // Info was in context, but available_books list blocked the LLM\n    RetrievalMiss        // Weaviate returned chunks that didn't contain the answer\n    TrueSilence          // The info actually isn't in the Gill Archive at all\n    LLMLaziness          // The info was there, but the LLM missed it\n}\n\nclass RAGAnalysis {\n    category FailureCategory\n    reasoning string @description(\"Brief explanation of why this category was chosen\")\n    fix_action string @description(\"Suggested fix (e.g., 'Add synonym for X' or 'Update book list')\")\n}\n\nfunction AnalyzeRAGFailure(question: string, context: string, manifest: string) -> RAGAnalysis {\n  client \"openai/deepseek/deepseek-chat\" // User prefers deepseek/deepseek-chat for this project\n  prompt #\"\n    Review this RAG failure for the John Gill Archive.\n    \n    USER QUESTION: {{ question }}\n    WEAVIATE CONTEXT: {{ context }}\n    AVAILABLE BOOKS: {{ manifest }}\n\n    Analyze why the system gave a 'No Information' response or failed to answer correctly.\n\n    In your 'reasoning', use Slack emojis to categorize the severity:\n    - 🔴 for ManifestBlock (Critical Configuration Error)\n    - 🟡 for RetrievalMiss (Search/Embedding Tuning Needed)\n    - ⚪ for TrueSilence (Data not in Archive)\n    - 🔵 for LLMLaziness (Model Logic Issue)\n\n    Keep the 'fix_action' to a single, actionable bullet point.\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "gill_extract.baml": "// BAML Schema for Gill Knowledge Graph Entity Extraction\n\n// 1. Define the Categories for the Knowledge Graph\nenum EntityCategory {\n  // Theology\n  Doctrine            // e.g., Justification, Election\n  Heresy              // e.g., Socinianism, Sabellianism\n  TypeOrSymbol        // e.g., The Rock, Scarlet Thread\n\n  // Persons (Granular)\n  BiblicalFigure      // e.g., Abraham, Moses, Peter\n  HistoricalFigure    // e.g., Alexander the Great, Nero\n  CitedAuthority      // e.g., Josephus, R. Solomon Jarchi, Maimonides\n  PeopleGroup         // e.g., Pharisees, Chaldeans\n\n  // Context\n  Location            // e.g., Canaan, River Jordan, Ephesus\n  TimePeriod          // e.g., \"The 70th Week\", \"Reign of Tiberius\"\n  \n  // Scholarship\n  OriginalWord        // Hebrew/Greek words defined (e.g., \"Sheol\", \"Logos\")\n  ManuscriptOrVersion // e.g., Septuagint, Vulgate, Targum\n\n  Unknown             // Use ONLY for UNRESOLVED_PRONOUNs\n}\n\n// 2. The Entity Structure\n// 👇 NEW: Helper Enum for Disambiguation\nenum BiblicalEra {\n  OldTestament\n  NewTestament\n  Intertestamental\n  ChurchHistory\n  NotApplicable\n}\n\nclass GillEntity {\n  name string @description(\"The entity name as it appears\")\n  category EntityCategory @description(\"The category this entity belongs to\")\n  \n  // 👇 CRITICAL FOR DISAMBIGUATION (The \"Joseph\" Fix)\n  biblical_era BiblicalEra @description(\"If a person, which era do they belong to? Use NotApplicable for concepts.\")\n  role string? @description(\"Specific role to distinguish same-named figures (e.g., 'Patriarch', 'Apostle', 'Husband of Mary').\")\n\n  normalized_name string? @description(\"Normalize: 'Christ' -> 'Jesus Christ'. For 'Joseph', leave as 'Joseph' and let era/role disambiguate.\")\n  description string? @description(\"A short 5-10 word context.\")\n}\n\n// 👇 NEW: Wrapper Class to catch Scripture Links\nclass ExtractionResult {\n  entities GillEntity[]\n  cross_references string[] @description(\"List of other Bible verses referenced in this text, normalized to 'BOOK_CH_VS' (e.g., 'ISA_53_06').\")\n}\n\n// 3. The Extraction Function\nfunction ExtractGillKnowledge(commentary_text: string, previous_entities: string?) -> ExtractionResult {\n  client OpenRouterText\n  \n  prompt #\"\n    Analyze this commentary by John Gill. Extract key entities and scripture references.\n    \n    **CRITICAL DISTINCTIONS:**\n    - 'BiblicalFigure': People who appear IN the Bible narrative (Abraham, Moses, Peter, Jesus, etc.)\n    - 'CitedAuthority': Scholars, Rabbis, or historians that GILL QUOTES (Josephus, Maimonides, Jerome, etc.)\n    - 'OriginalWord': Hebrew or Greek words that Gill defines or explains (mark the transliterated word)\n    - 'Location': Physical places mentioned\n    - 'TimePeriod': Historical periods or eras\n    - 'Doctrine': Theological concepts (Justification, Election, Trinity, etc.)\n    - 'Heresy': False teachings Gill refutes\n    - 'TypeOrSymbol': Biblical types/symbols (The Rock = Christ, Manna = Word of God, etc.)\n    - 'HistoricalFigure': Non-biblical historical persons mentioned\n    - 'PeopleGroup': Ethnic or religious groups (Pharisees, Sadducees, Chaldeans, etc.)\n    - 'ManuscriptOrVersion': Biblical manuscripts or versions (Septuagint, Vulgate, Targum, etc.)\n    \n    **NORMALIZATION RULES:**\n    - For Jesus: Normalize \"Christ\", \"the Lord\", \"our Saviour\" -> \"Jesus Christ\"\n    - For God: Normalize \"the Lord\", \"Jehovah\", \"the Almighty\" -> \"God\"\n    - For locations: Use standard names (e.g., \"the land of Canaan\" -> \"Canaan\")\n    - For cited authorities: Include title if mentioned (e.g., \"R. Solomon Jarchi\", \"Josephus\")\n    \n    **DISAMBIGUATION INSTRUCTIONS:**\n    - For common names (Mary, Joseph, John, James, Saul), you MUST fill the 'biblical_era' and 'role' fields accurately.\n    - Example: \"Joseph was sold\" -> era: OldTestament, role: \"Patriarch/Son of Jacob\"\n    - Example: \"Joseph took the child\" -> era: NewTestament, role: \"Husband of Mary\"\n    - **INTRA-ERA COLLISIONS:** If a name refers to multiple people in the SAME era (e.g. multiple Zechariahs in OT, multiple Marys in NT), you MUST specify their distinct identity in the 'role' field.\n      - BAD: name=\"Zechariah\", role=\"Biblical Figure\"\n      - GOOD: name=\"Zechariah\", role=\"Prophet / Son of Berechiah\"\n      - GOOD: name=\"Zechariah\", role=\"Priest / Son of Jehoiada\"\n    - **WATCH FOR TYPOLOGY:** Gill frequently compares OT figures to NT figures. If he mentions \"Joseph\" (NT) inside a commentary on \"Joseph\" (OT), extract them as TWO SEPARATE entities.\n\n    **CRITICAL RULE: SCRIPTURE CITATIONS VS. ENTITIES**\n    Gill frequently abbreviates Bible books (e.g., \"Rom. i. 4\", \"Mark xvi. 11\").\n    \n    1. **CHECK THE PATTERN:** Does the \"Name\" look like a book abbreviation followed by numbers (Roman or Digit)?\n       - \"Rom. i. 4\" -> This is a CITATION.\n       - \"Mark xvi. 11\" -> This is a CITATION.\n       - \"Mark\" (alone) -> This is a BIBLICAL FIGURE.\n       \n    2. **THE ACTION:** - If it is a CITATION: Add it to the 'cross_references' list. **DO NOT** create a GillEntity for it.\n       - If it is a PERSON: Create a GillEntity with category 'BiblicalFigure'.\n       \n    **Ambiguity Check:** \"Mark\" is a person. \"Mark xvi.\" is a book. Distinguish them by looking for the chapter numbers immediately following.\n\n    **SCRIPTURE REFERENCES:**\n    - Extract any direct bible verses Gill cites to support his argument.\n    - Normalize them to the format: BOOK_CHAPTER_VERSE (e.g., MAT_03_16).\n    \n    **PRONOUN RESOLUTION:**\n    If the text relies on pronouns ('he', 'they', 'the king') rather than explicit names, review the `previous_entities` list provided below.\n    - If context clearly aligns the pronoun with a previous entity, extract that specific name.\n    - **IF AND ONLY IF** you cannot confidently resolve the pronoun using the provided context, return the exact string \"UNRESOLVED_PRONOUN\" as the `name` of a Theological Entity.\n    \n    Previous Entities (Context Hint):\n    {{ previous_entities }}\n\n    Commentary Text:\n    {{ commentary_text }}\n    \n    {{ ctx.output_format }}\n  \"#\n}\n",
    "main.baml": "// BAML configuration for OCR metadata validation with Ollama\n\n// Define the metadata structure\nclass Metadata {\n  book_name string? @description(\"The name of the book of the bible found at the top center of the image\")\n  chapter int? @description(\"The chapter number (converted from Roman numerals to decimal). For chapter-spanning pages, this is the first chapter.\")\n  verse string? @description(\"The verse number, range (e.g. '1-3'), list (e.g. '1,2,3'), or chapter-spanning notation\")\n  page_number int? @description(\"The page number found at top left or top right\")\n  no_verse_markers bool? @description(\"Set to true ONLY if there are NO verse (Ver.) markers on this page except in header.\")\n}\n\n// Define the core metadata structure (split validation step 1)\nclass MetadataCore {\n  book_name string? @description(\"The name of the book of the bible found at the top center of the image\")\n  chapter int? @description(\"The chapter number (converted from Roman numerals to decimal). For chapter-spanning pages, this is the first chapter.\")\n  page_number int? @description(\"The page number found at top left or top right\")\n}\n\n// Define the verse metadata structure (split validation step 2)\nclass MetadataVerses {\n  verse string? @description(\"The verse number, range (e.g. '1-3'), list (e.g. '1,2,3'), or chapter-spanning notation\")\n  no_verse_markers bool? @description(\"Set to true ONLY if there are NO verse (Ver.) markers on this page except in header.\")\n}\n\n// Define the extracted text structure for OpenRouter\nclass ExtractedText {\n  text string @description(\"The extracted text from the image\")\n}\n\n// Define the Ollama client using OpenAI-compatible endpoint\nclient<llm> Ollama {\n  provider openai\n  options {\n    model \"qwen2.5vl:32b\"\n    base_url \"http://192.168.1.188:11434/v1\"\n    //model \"qwen3-vl-8k:32b\"\n    //base_url \"http://192.168.1.179:11434/v1\"\n    api_key \"ollama\"\n    temperature 0.1\n    options: {\n      num_ctx: 2048\n    }\n  }\n}\n\n// Define the Ollama client for oss-gpt:20b (text normalization)\nclient<llm> OllamaGPT {\n  provider openai\n  options {\n    model \"qwen3-8k:32b\"\n    base_url \"http://192.168.1.188:11434/v1\"\n    api_key \"ollama\"\n    temperature 0.1\n  }\n}\n\n// Define the OpenRouter client\nclient<llm> OpenRouter {\n  provider openai\n  options {\n    base_url \"https://openrouter.ai/api/v1\"\n    api_key env.OPENROUTER_API_KEY\n    model \"qwen/qwen3-vl-235b-a22b-thinking\"\n  }\n}\n\n// Define the OpenRouter client for text-only tasks\nclient<llm> OpenRouterText {\n  provider openai\n  options {\n    base_url \"https://openrouter.ai/api/v1\"\n    api_key env.OPENROUTER_API_KEY\n    model \"x-ai/grok-4.1-fast\"\n  }\n}\n\n// Define the LiteLLM proxy client (routes to local Ollama/gemma4 via cluster DNS)\nclient<llm> LocalRouter {\n  provider openai\n  options {\n    base_url env.LITELLM_PROXY_URL\n    api_key \"anything\"\n    model \"local-router\"\n    temperature 0.0\n  }\n}\n\n// Define the validation function (LEGACY / MONOLITHIC)\nfunction ValidateOCRMetadata(\n  image: image,\n  ocr_metadata: Metadata,\n  body_verses: string?\n) -> Metadata {\n  client Ollama\n  \n  prompt #\"\n    Please check the OCR metadata returned below for accuracy in the reported page number, book, chapter and verse this image is referring to. These will all be found at the top of the image. The page number will be either on the top far left or top far right. The book will be in the top center. And the chapter and verse will be on the opposite side of the page number in the format of 'CH. <roman numeral chapter> V. <verse number, range or list>'. Numbers should be converted to decimal. Be careful to interpret numbers properly because the font used is curly and thus 2 is often confused for 9. Verses can also be derived from the references in the text body which look like 'Ver. <verse number>'.\n    \n    VERSE FORMATTING:\n    - Single verse: \"3\"\n    - Range: \"3-5\" (verses 3 through 5)\n    - List: \"3,4,5\" (specific verses)\n    - Chapter-spanning: \"27:42-46,28:1\" (verses 42-46 of chapter 27, then verse 1 of chapter 28)\n    \n    CHAPTER-SPANNING PAGES:\n    Some pages span multiple chapters. The header will show two chapter markers:\n    \"CH. XXVII. V. 42-46. XXVIII. V. 1\" should be formatted as \"27:42-46,28:1\"\n    For chapter-spanning pages, set the chapter field to the FIRST chapter number (27 in this example).\n    \n    Current OCR Metadata:\n    - Book: {{ ocr_metadata.book_name }}\n    - Chapter: {{ ocr_metadata.chapter }}\n    - Detected Header Verses: {{ ocr_metadata.verse }}\n   {% if body_verses %}\n    - Detected Body Verses: {{ body_verses }}\n   {% endif %}\n    - Page: {{ ocr_metadata.page_number }}\n       \n    Please review the image and provide the corrected metadata if any errors are found. If the OCR is correct, return the same values. Pay special attention to:\n    1. Distinguishing between 2 and 9 in the curly font\n    2. Correctly parsing chapter-spanning headers into the chapter:verse notation\n    3. Ensuring the chapter field reflects the first chapter in chapter-spanning pages\n    {% if body_verses %}\n    4. Reconciling header range with detected body verses by using these body verses as a strong hint. \n      - If the header says \"10-15\" but body verses are exactly \"10, 11, 12, 13\" (and page layout suggests end of section), the header might be wrong or reading a smudge.\n      - If the body verses are sequential and consistent, favor them over a mismatched header.\n    {% endif %}\n    \n    {{ _.role(\"user\") }}\n    {{ image }}\n    \n    {{ ctx.output_format }}\n  \"#\n}\n\n// Define the validation function (STEP 1: CORE METADATA)\nfunction ValidateMetadataCore(\n  image: image,\n  ocr_metadata: MetadataCore\n) -> MetadataCore {\n  client Ollama\n  \n  prompt #\"\n    Please check the OCR metadata returned below specifically for the PAGE NUMBER, BOOK NAME, and CHAPTER NUMBER.\n    \n    LOCATION:\n    - Page Number: Top far left OR top far right.\n    - Book Name: Top center.\n    - Chapter Number: Opposite side of page number, usually \"CH. <Roman Numeral>\".\n    \n    INSTRUCTIONS:\n    - Return the corrected values if possible.\n    - Distinguish between 2 and 9 carefully (curly font).\n    - Convert Roman numerals to decimal (e.g. XXVII -> 27).\n    - If the page spans multiple chapters (e.g. \"CH. XXVII... XXVIII\"), use the FIRST chapter number.\n    \n    Current OCR Metadata:\n    - Book: {{ ocr_metadata.book_name }}\n    - Chapter: {{ ocr_metadata.chapter }}\n    - Page: {{ ocr_metadata.page_number }}\n    \n    {{ _.role(\"user\") }}\n    {{ image }}\n    \n    {{ ctx.output_format }}\n  \"#\n}\n\n// Define the validation function (STEP 2: VERSES)\nfunction ValidateMetadataVerses(\n  image: image,\n  chapter: int?,\n  verse_hint: string?,\n  body_verses: string?\n) -> MetadataVerses {\n  client Ollama\n  \n  prompt #\"\n    Please check the OCR metadata returned below for accuracy by identifying the VERSE RANGE described in the header of this image.\n    \n    LOCATION:\n    - Usually \"V. <number>\", \"V. <start>-<end>\", or similar.\n    - Found near the Chapter number in the header.\n    \n    VERSE FORMATTING:\n    - Single verse: \"3\"\n    - Range: \"3-5\"\n    - List: \"3,4,5\"\n    - Chapter-spanning: \"27:42-46,28:1\"\n    \n    INSTRUCTIONS:\n    1. Read the header verse notation carefully since it uses a curly font. distinguish 2 vs 9.\n    2. If the page spans chapters (e.g. \"CH. 27 V. 40 ... CH. 28 V. 1\"), use the chapter-spanning notation.\n    3. Use the provided Body Verses as a strong hint for what verses are actually discussed on the page.\n    4. ALWAYS convert Roman numerals to decimal numbers. (e.g. 'IV' -> '4'). Never return Roman numerals.\n    \n    EXAMPLES:\n    - \"CH. IV. V. 1-7\" -> \"4:1-7\"\n    - \"CH. III. V. 34, 35, IV. V. 1\" -> \"3:34,35,4:1\"\n    \n    CONTEXT:\n    - Chapter: {{ chapter }}\n    - OCR Header Verse Hint: {{ verse_hint }}\n    {% if body_verses %}\n    - Detected Body Verses: {{ body_verses }}\n    {% endif %}\n    \n    {{ _.role(\"user\") }}\n    {{ image }}\n    \n    {{ ctx.output_format }}\n  \"#\n}\n\n// Define the image text extraction function for OpenRouter\nfunction ExtractTextFromImage(\n  image: image,\n  book: string?,\n  chapter: string?,\n  verse: string?,\n  page_number: string?,\n  hebrew_text: string?,\n  greek_text: string?,\n  ocr_text: string?\n) -> string {\n  client OpenRouter\n  \n  prompt #\"\n    Extract the text from the image in markdown format. Some words might be in Greek, Hebrew or Arabic, especially in footnotes, please include these words in their proper language. Please link the footnote to its place in the text.\n    \n    IMPORTANT: The image has TWO COLUMNS but you must MERGE them into a SINGLE continuous text output. Read the left column completely from top to bottom first, then continue with the right column from top to bottom. Handle text that is hyphenated from one column to the other by combining the hyphenated word. Do NOT preserve the two-column layout in your output - provide a single flowing text.\n    \n    FOOTNOTES: The footnotes ONLY use lower case lettering (a, b, c, etc.). There can be duplicate footnote letters when they are reused in different paragraphs. Include all footnotes at the end of their respective paragraph or section, properly linked with their lowercase letter markers.\n    \n    {% if ocr_text %}\n    The output of an OCR tool is attached below and should be ONLY used to maintain accuracy in matching the original word for word since it gets some words wrong. The OCR often fails to detect the footnote lettering. OCR also struggles with the languages so use the image for those.\n    {% endif %}\n    \n    {% if hebrew_text %}\n    Original Hebrew verse the commentary is referring to is provided as a reference to ensure the Hebrew in the text is properly interpreted. Please match the Hebrew letter order as it is in the image and reference.\n    {% endif %}\n    \n    {% if greek_text %}\n    Original Greek verse the commentary is referring to is provided as a reference to ensure the Greek in the text is properly interpreted. Please match the Greek letter order as it is in the image and reference.\n    {% endif %}\n    \n    {% if book or chapter or verse or page_number %}\n    \n    === METADATA ===\n    {% if book %}Book: {{ book }}\n    {% endif %}{% if chapter %}Chapter: {{ chapter }}\n    {% endif %}{% if verse %}Verse(s): {{ verse }}\n    {% endif %}{% if page_number %}Page Number: {{ page_number }}\n    {% endif %}{% endif %}\n    \n    {% if hebrew_text %}\n    \n    === ORIGINAL HEBREW VERSES ===\n    {{ hebrew_text }}\n    {% endif %}\n    \n    {% if greek_text %}\n    \n    === ORIGINAL GREEK VERSES ===\n    {{ greek_text }}\n    {% endif %}\n    \n    {% if ocr_text %}\n    \n    === OCR OUTPUT (For Reference Only) ===\n    {{ ocr_text }}\n    {% endif %}\n    \n    {{ _.role(\"user\") }}\n    {{ image }}\n  \"#\n}\n\n// Define the verse chunk structure for alignment\nclass VerseChunk {\n  verse_ref string @description(\"Standardized verse reference, e.g., 'MAT 03:16'. Use 3-letter book codes (GEN, EXO, MAT, etc.)\")\n  start_phrase string @description(\"Unique starting phrase of the commentary for this verse (approx 5-10 words). Must be verbatim from the text.\")\n  end_phrase string @description(\"Unique ending phrase of the commentary for this verse (approx 5-10 words). Must be verbatim from the text.\")\n}\n\n// Define the verse extraction function\nfunction ExtractVersesFromMarkdown(\n  markdown_text: string\n) -> VerseChunk[] {\n  client OpenRouterText\n  \n  prompt #\"\n    Analyze the following commentary text and split it into verse chunks. Each chunk corresponds to a specific verse reference (e.g., \"Ver. 1.\", \"Ver. 2.\").\n    \n    CRITICAL: You must extract EVERY single verse found in the text. Do not skip any.\n    \n    - Look for explicit markers like \"Ver. 31.\"\n    - If there is text before the first explicit marker that belongs to a previous verse, extract it as a separate chunk and infer the verse reference (e.g., if \"Ver. 31\" follows, the previous text is likely \"Ver. 30\").\n    - Do not stop after the first verse. Process the entire text.\n    \n    For each verse chunk:\n    1. Identify the verse reference. Convert it to a standardized format (e.g., \"GEN 01:01\").\n    2. Extract the first 10-15 words IMMEDIATELY after the verse marker (e.g., \"Ver. 31.\") as the `start_phrase`. This often includes the QUOTED VERSE TEXT (which may be in italics or marked with * or brackets) followed by commentary. DO NOT skip the verse quotation.\n    3. Extract the last 10-15 words of the commentary text for that verse as the `end_phrase`.\n    \n    CRITICAL: The `start_phrase` and `end_phrase` MUST be EXACT substrings from the provided text. Do not paraphrase or modify them. They will be used for fuzzy matching against the original OCR data.\n    \n    If a chunk covers multiple verses (e.g., \"Ver. 4, 5.\"), create a separate entry for each verse if possible, or one entry with the combined range if the text is merged. Ideally, split them if the text clearly delineates them. If the text is a single block for multiple verses, use the range in the ref (e.g., \"GEN 01:04-05\").\n    \n    Input Text:\n    {{ markdown_text }}\n    \n    {{ _.role(\"user\") }}\n    Extract the verse chunks.\n    \n    {{ ctx.output_format }}\n  \"#\n}\n\n// Define the markdown normalization function for John Gill Commentary\nfunction NormalizeGillMarkdown(raw_markdown: string) -> string {\n  client OllamaGPT\n  \n  prompt #\"\n    You are a specialized theological editor responsible for formatting John Gill's Bible Commentary.\n    \n    Objective: Normalize the raw OCR text into clean, structured Markdown while strictly preserving the 18th-century stylistic conventions (specifically the Verse Lemma format).\n    \n    Input: Raw Markdown text derived from OCR/Vision models (which may contain page headers, varying footnote markers, and layout artifacts).\n    Output: Clean, consistent Markdown ready for database ingestion.\n    \n    === 1. STRUCTURAL RULES (STRICT) ===\n    \n    A. Remove ONLY Metadata Headers (at the very top of the page):\n    - Page numbers (e.g., \"90\", \"page 90\")\n    - Book/chapter markers like \"GENESIS\", \"CH. I. V. 3\"\n    - These are typically short lines at the very beginning, NOT part of the commentary.\n    \n    B. PRESERVE ALL Commentary Text:\n    - CRITICAL: Text that starts mid-sentence (spillover from previous page) MUST be preserved.\n    - Example: If the file starts with \"triarchs: but yet such a variety...\" this is continuation text from the previous page and MUST be kept.\n    - Only remove obvious page metadata, never remove actual commentary content.\n    \n    C. Chapter Headings:\n    - Format Chapter starts as a standard Markdown Header 1.\n    - Input: **CHAP. I.** or CHAP. 1.\n    - Output: # Chapter 1\n    \n    D. Verse Commentary (The Lemma Style):\n    - Constraint: Do NOT use ### Verse 3. Keep the archaic format.\n    - Format: Start every verse commentary on a new line with the exact pattern: Ver. {number}.\n    - Normalization:\n      - If input is V. 6., change to Ver. 6.\n      - If input is Verse 6., change to Ver. 6.\n      - If input is Ver 6, change to Ver. 6. (ensure periods are present).\n    - The Lemma: Ensure the bracketed lemma text follows immediately.\n      - Example: Ver. 6. And Jesus went, &c.]\n    \n    E. Paragraphs:\n    - Remove excessive newlines. Paragraphs should be separated by a single blank line.\n    \n    === 2. FOOTNOTE NORMALIZATION RULES (CRUCIAL) ===\n    \n    The raw text uses inconsistent markers (e.g., ^a^, ᵃ, (1), *, †, <sup>). You must standardize them to Markdown.\n    \n    CRITICAL: Do NOT invent or add new footnote markers. Only normalize markers that ALREADY EXIST in the original text.\n    \n    A. In-Text Markers:\n    - Convert EXISTING footnote markers in the body text to standard numerical Markdown citations: [^1], [^2], [^3].\n    - Number them sequentially starting from 1 for the page.\n    - Example: \"...as Aben Ezra observes^a^\" → \"...as Aben Ezra observes[^1]\"\n    - If there is NO footnote marker in the original (e.g., \"Aben Ezra observes\" with no ^a^ or superscript), do NOT add one.\n    \n    B. Footnote Definitions:\n    - Move ALL footnote definitions to the very bottom of the text.\n    - Format them as: [^1]: {Content}\n    - Matching: You must intelligently match the in-text marker to the correct definition based on context or the original marker symbol (e.g., if text has ^a^ and footer has a Vid. Josephus, link them as [^1]).\n    - Formatting: Remove the original marker letters (a, b, *) from the definition text.\n      - Bad: [^1]: a Vid. Josephus...\n      - Good: [^1]: Vid. Josephus...\n    - New section markers should start with letter 'a' unless the conversion interpreted them wrong. Spill over markers will follow the lettering order from the previous page potentially resulting in duplicate letters. BE CAREFUL to match them correctly.\n    \n    === 3. CONTENT INTEGRITY RULES ===\n    \n    - Hebrew/Greek: NEVER alter or remove Hebrew, Greek, or Arabic text. Keep it exactly as is.\n    - Italics: Ensure Bible quotations or emphasized words use *asterisks* (not _underscores_).\n    - Spelling: Do not modernize 18th-century spelling (e.g., \"shewn\", \"hath\")\n    - Spillover Text: ALWAYS preserve text that continues from a previous page, even if it starts mid-sentence.\n    \n    {{ _.role(\"user\") }}\n    \n    Please normalize the following raw OCR markdown:\n    \n    {{ raw_markdown }}\n  \"#\n}\n",
    "query_router.baml": "// BAML Schema for Query Expansion and Routing\n// Translates modern user queries into Gill-friendly theological terms\n\nclass OptimizedQuery {\n    expanded_search_terms string @description(\"A rich search string combining the user's modern terms with 18th-century theological synonyms John Gill would use (e.g., 'Christophany' -> 'Angel of the Lord, divine appearance').\")\n    official_entities string[] @description(\"A list of official graph entities mapped from the query based on the provided manifest. Return an empty list if none match.\")\n}\n\nfunction OptimizeSearchQuery(user_query: string, available_entities: string[]) -> OptimizedQuery {\n  client LocalRouter\n  prompt #\"\n    You are a theological search translator for the John Gill Archive (18th-century Calvinist/Baptist theology).\n    The user asked: {{ user_query }}\n    \n    1. **QUERY EXPANSION**: Expand their modern search terms into 18th-century synonyms that John Gill would likely use in his commentary.\n       - Example: 'Christophany' -> 'The Angel of the Lord, appearance of the Son of God, divine manifestation'\n       - Example: 'Rapture' -> 'The coming of Christ, the gathering of the saints, the resurrection'\n    \n    2. **ENTITY MAPPING**: Map their concepts to these official database entities if applicable:\n    {{ available_entities }}\n  \n    {{ ctx.output_format }}\n\n    CRITICAL: You must output ONLY the raw JSON object. Do not include any markdown formatting (` ```json `), do not include any preamble, and do not include any explanations. Start immediately with { and end with }.\n  \"#\n}\n",
    "resolution.baml": "// BAML Schema for Page Boundary Pronoun Resolution\n// Resolves \"He\"/\"They\" across physical page splits by looking at previous context\n\nclass ResolvedPronoun {\n    resolved_entity_names string[] @description(\"The actual names of the entities that the pronoun refers to, selected strictly from the previous_entities list.\")\n}\n\nfunction ResolveBoundaryPronouns(unresolved_text: string, previous_text: string, previous_entities: string[]) -> ResolvedPronoun {\n  client OpenRouterText\n  prompt #\"\n    You are an expert in John Gill's 18th-century theological writings.\n    We have a text chunk that starts with an unresolved pronoun (like \"He\", \"They\", or \"The Apostle\") because it was split across a physical page boundary.\n    \n    PREVIOUS PAGE CONTEXT:\n    {{ previous_text }}\n    \n    ENTITIES MENTIONED ON PREVIOUS PAGE:\n    {{ previous_entities }}\n    \n    CURRENT TEXT (STARTS WITH PRONOUN):\n    {{ unresolved_text }}\n    \n    Identify who the pronouns in the CURRENT TEXT are referring to, based on the PREVIOUS PAGE CONTEXT.\n    Return ONLY the exact entity names from the provided list. If none match, return an empty list.\n    {{ ctx.output_format }}\n  \"#\n}\n",
}

